export default function Stepper({ className, value = "1", onChange }) {
  const handleDecrement = () => {
    const num = parseInt(value, 10);
    if (num > 0 && onChange) onChange(String(num - 1));
  };

  const handleIncrement = () => {
    const num = parseInt(value, 10);
    if (num < 10 && onChange) onChange(String(num + 1));
  };

  return (
    <div className={className || "stepper"}>
      <button
        className="stepper-button"
        onClick={handleDecrement}
        aria-label="Decrement"
      >
        <div className="stepper-icon">
          <div className="stepper-icon-bar stepper-icon-bar-horizontal" />
        </div>
      </button>
      <p className="stepper-value">{value}</p>
      <button
        className="stepper-button"
        onClick={handleIncrement}
        aria-label="Increment"
      >
        <div className="stepper-icon">
          <div className="stepper-icon-bar stepper-icon-bar-horizontal" />
          <div className="stepper-icon-bar stepper-icon-bar-vertical" />
        </div>
      </button>
    </div>
  );
}

