import { useState } from 'react';
import './Stepper.css';

export default function Stepper({ className, value: initialValue = 1, onChange }) {
  const [value, setValue] = useState(initialValue);

  const handleDecrement = () => {
    const newValue = Math.max(0, value - 1);
    setValue(newValue);
    onChange?.(newValue);
  };

  const handleIncrement = () => {
    const newValue = Math.min(10, value + 1);
    setValue(newValue);
    onChange?.(newValue);
  };

  return (
    <div className={className || 'stepper'} data-node-id="17:2" role="spinbutton">
      <button
        className="stepper-button"
        data-node-id="17:3"
        role="button"
        aria-label="Decrement"
        onClick={handleDecrement}
      >
        <div className="stepper-icon" data-node-id="17:4">
          <div className="icon-bar-h" data-node-id="17:5" />
        </div>
      </button>
      <p className="stepper-value" data-node-id="17:6" role="status">
        {value}
      </p>
      <button
        className="stepper-button"
        data-node-id="17:7"
        role="button"
        aria-label="Increment"
        onClick={handleIncrement}
      >
        <div className="stepper-icon" data-node-id="17:8">
          <div className="icon-bar-h" data-node-id="17:9" />
          <div className="icon-bar-v" data-node-id="17:10" />
        </div>
      </button>
    </div>
  );
}

import { useState } from 'react';
import '../styles/stepper.css';

export default function Stepper({ className, value: initialValue = 1, min = 0, max = 10, onChange }) {
  const [value, setValue] = useState(parseInt(initialValue, 10));

  const handleDecrement = () => {
    const newValue = Math.max(min, value - 1);
    setValue(newValue);
    onChange?.(newValue);
  };

  const handleIncrement = () => {
    const newValue = Math.min(max, value + 1);
    setValue(newValue);
    onChange?.(newValue);
  };

  return (
    <div className={className || 'stepper'} role="spinbutton" aria-valuemin={min} aria-valuemax={max} aria-valuenow={value}>
      <button
        className="stepper-button stepper-decrement"
        onClick={handleDecrement}
        disabled={value <= min}
        aria-label="Decrement"
      >
        <svg className="stepper-icon" viewBox="0 0 12 12" width="12" height="12">
          <line x1="1" y1="6" x2="11" y2="6" stroke="currentColor" strokeWidth="2" />
        </svg>
      </button>
      <div className="stepper-value">{value}</div>
      <button
        className="stepper-button stepper-increment"
        onClick={handleIncrement}
        disabled={value >= max}
        aria-label="Increment"
      >
        <svg className="stepper-icon" viewBox="0 0 12 12" width="12" height="12">
          <line x1="1" y1="6" x2="11" y2="6" stroke="currentColor" strokeWidth="2" />
          <line x1="6" y1="1" x2="6" y2="11" stroke="currentColor" strokeWidth="2" />
        </svg>
      </button>
    </div>
  );
}

